 s=pd.Timestamp(s); e=pd.Timestamp(e); z=0
 for d in pd.date_range(s.normalize(),e.normalize()):
  if d.weekday()<5:
   lo=max(s,d+pd.Timedelta(hours=9)); hi=min(e,d+pd.Timedelta(hours=17))
